/**
 * The venue account lists against the keeper's own output (FRONTEND.md §10.1 SHORT):
 * `vectors/keeper-vectors.json` is generated by `vectors/keeper_vectors.rs` from
 * `shortwin_keeper::venue` on markets whose caches the program's own listing helpers wrote, with
 * the dumped mainnet accounts of `tests/fixtures` where the keeper reads live state.
 */
import type { VenueExtras } from '@shortwin/client';
import { AccountRole, type Address, createNoopSigner, type Instruction } from '@solana/kit';
import { describe, expect, it } from 'vitest';
import { readRepo, readRepoBytes } from '../test/repo.ts';
import { kindName } from './constants.ts';
import {
    extrasCandidates,
    keeperRecipientIndex,
    type MarketKeys,
    pammCreatorVaultPrep,
    readMetas,
    readSet,
    tradeExtras,
} from './lists.ts';
import type { RawAccount } from './readers.ts';

interface VMeta {
    key: string;
    w: boolean;
}
interface VSeed {
    kind: number;
    len: number;
    bytes: number[];
}
interface VEntry {
    kind: number;
    writable: number;
    nSeeds: number;
    key: string;
    seeds: VSeed[];
}
interface VSet {
    count: number;
    entries: VEntry[];
}
interface VCase {
    name: string;
    kind: number;
    market: Record<string, unknown> & { poolCache: string[]; flags: number };
    read?: { slot: number; file: string; owner: string }[];
    readSet?: string[];
    tradeMetas?: VMeta[];
    crankMetas?: VMeta[];
    tradeExtras?: VMeta[] | null;
    creatorVaultPrep?: { payer: string; keys: string[] } | null;
    venueExtras?: string;
    sets?: { current: VSet; previous: VSet; stable: VSet }[];
    sell?: { set: number; bumps: number[]; metas: VMeta[] }[];
    buy?: { set: number; bumps: number[]; metas: VMeta[] }[];
}

const vectors = JSON.parse(readRepo('apps/web/src/venues/vectors/keeper-vectors.json')) as { cases: VCase[] };

function marketOf(c: VCase): MarketKeys {
    return { ...(c.market as object), flags: c.market.flags, poolCache: c.market.poolCache } as unknown as MarketKeys;
}

function readOf(c: VCase, len: number): (RawAccount | null)[] {
    const read: (RawAccount | null)[] = Array.from({ length: len }, () => null);
    for (const r of c.read ?? []) {
        read[r.slot] = {
            address: '11111111111111111111111111111111' as Address,
            owner: r.owner as Address,
            lamports: 1n,
            executable: false,
            data: readRepoBytes(`tests/fixtures/${r.file}`),
        };
    }
    return read;
}

const flat = (ms: readonly { address: Address; role: AccountRole }[]): VMeta[] =>
    ms.map((m) => ({ key: m.address, w: m.role === AccountRole.WRITABLE || m.role === AccountRole.WRITABLE_SIGNER }));

const listCases = vectors.cases.filter((c) => c.readSet);
const extrasCasesV = vectors.cases.filter((c) => c.sets);

describe('venue account lists = the keeper venue.rs', () => {
    it('has a vector for every venue', () => {
        const kinds = new Set(listCases.map((c) => kindName(c.kind)));
        expect([...kinds].sort()).toEqual(
            ['mock', 'none', 'pump_curve', 'pump_migrating', 'pump_swap', 'raydium_cpmm', 'raydium_v4'].sort(),
        );
    });

    for (const c of listCases) {
        it(`${c.name}: ReadSet, writability and TradeExtras`, async () => {
            const kind = kindName(c.kind);
            if (!kind) throw new Error(`kind ${c.kind}`);
            const m = marketOf(c);
            const keys = await readSet(kind, m);
            expect(keys).toEqual(c.readSet);
            expect(flat(readMetas(kind, keys, true))).toEqual(c.tradeMetas);
            expect(flat(readMetas(kind, keys, false))).toEqual(c.crankMetas);
            const read = readOf(c, keys.length);
            if (c.tradeExtras === null || c.tradeExtras === undefined) {
                await expect(tradeExtras(kind, m, read, keeperRecipientIndex)).rejects.toThrow();
            } else {
                expect(flat(await tradeExtras(kind, m, read, keeperRecipientIndex))).toEqual(c.tradeExtras);
            }
            const payer = createNoopSigner(
                (c.creatorVaultPrep?.payer ?? '11111111111111111111111111111111') as Address,
            );
            const prep: Instruction | null = await pammCreatorVaultPrep(payer, m, kind, read);
            if (c.creatorVaultPrep) {
                expect(prep?.accounts?.map((a) => a.address)).toEqual(c.creatorVaultPrep.keys);
                expect([...(prep?.data ?? [])]).toEqual([1]);
            } else expect(prep).toBeNull();
        });
    }

    it('picks a live recipient at random but always one the program accepts', async () => {
        const c = listCases.find((x) => x.name === 'pump_curve');
        if (!c) throw new Error('no pump_curve vector');
        const m = marketOf(c);
        const read = readOf(c, 7);
        const seen = new Set<string>();
        for (let i = 0; i < 24; i++) {
            const x = await tradeExtras('pump_curve', m, read);
            seen.add(x[6]?.address ?? '');
        }
        const global = JSON.parse(readRepo('tests/fixtures/manifest.json')).accounts.find(
            (a: { name: string }) => a.name === 'pump_global',
        ).decoded.fee_recipients as string[];
        for (const k of seen) expect(global).toContain(k);
        expect(seen.size).toBeGreaterThan(1);
    });
});

function venueExtrasOf(c: VCase): VenueExtras {
    const set = (s: VSet) => ({
        version: 1,
        count: s.count,
        pad: new Uint8Array(3),
        entries: s.entries.map((e) => ({
            kind: e.kind,
            writable: e.writable,
            nSeeds: e.nSeeds,
            pad: new Uint8Array(5),
            key: e.key as Address,
            seeds: e.seeds.map((p) => ({ kind: p.kind, len: p.len, bytes: new Uint8Array(p.bytes) })),
        })),
    });
    return {
        sets: (c.sets ?? []).map((x) => ({
            current: set(x.current),
            previous: set(x.previous),
            stable: set(x.stable),
            currentSince: 1n,
        })),
    } as unknown as VenueExtras;
}

describe('extras candidates = the keeper (A41)', () => {
    for (const c of extrasCasesV) {
        it(`${c.name}: current, none, previous, stable with canonical template bumps`, async () => {
            const kind = kindName(c.kind);
            if (!kind) throw new Error(`kind ${c.kind}`);
            const m = marketOf(c);
            const ve = venueExtrasOf(c);
            for (const [ix, want] of [
                [0, c.sell],
                [1, c.buy],
            ] as const) {
                const got = await extrasCandidates(kind, ix, m, ve);
                expect(got.map((g) => ({ set: g.sel.set, bumps: [...g.sel.bumps], metas: flat(g.metas) }))).toEqual(
                    want,
                );
                for (const g of got) if (g.metas.length) expect(g.metas[0]?.address).toBe(c.venueExtras);
            }
        });
    }

    it('without a VenueExtras account there is only `none`', async () => {
        const c = listCases.find((x) => x.name === 'mock');
        if (!c) throw new Error('no mock vector');
        const got = await extrasCandidates('mock', 0, marketOf(c), null);
        expect(got.map((g) => g.label)).toEqual(['none']);
    });
});
